import{C as t,o as a,c as i,E as r,k as o}from"./chunks/framework.DLvxyDDa.js";const n="3.0.3",s={title:"service-kapture",description:"Capture application snapshots as a service.\n\n**kapture** drives a headless browser ([Puppeteer](https://pptr.dev/)) on a [Kano](https://kalisio.github.io/kano/)-like application and returns the rendered page as a PNG image. The target application, its token and its name come from the `APP_URL`, `APP_JWT` and `APP_NAME` environment variables, and every request can override them along with the layers, the view, the size and the timings.\n\nThis service is not a Feathers application: it is a plain Express server exposing two routes at the root, with no API prefix.\n",version:"1.0.0"},p=[{bearerAuth:[]}],c=[{name:"Health",description:"Service status"},{name:"Capture",description:"Snapshot rendering"}],l={"/healthcheck":{get:{tags:["Health"],summary:"Service health check",operationId:"healthcheck",description:'Always answers `200` with `{ "isRunning": true }` as soon as the server accepts connections. Unlike the other services of the ekosystem, it reports neither a name nor a version.',security:[],responses:{200:{description:"Service is up",content:{"application/json":{schema:{type:"object",required:["isRunning"],properties:{isRunning:{type:"boolean",example:!0}}}}}}}}},"/capture":{post:{tags:["Capture"],summary:"Render a snapshot of the application",operationId:"capture",description:"Opens the target application in a headless browser, applies the requested view, waits for the network to settle and returns a full-page PNG screenshot.\n\nThe body can be either a **capture request** (`layers`, `bbox`, `size`, …), or a **GeoJSON** `Feature` / `FeatureCollection`, in which case the features are uploaded to the application and rendered as an overlay. Both can be combined by adding the capture properties next to the GeoJSON ones.\n\nThe request body size is limited by the `BODY_LIMIT` environment variable (`100kb` by default), which is quickly reached when embedding features — a payload above the limit is rejected by the body parser before the route is reached.\n",requestBody:{required:!0,content:{"application/json":{schema:{$ref:"#/components/schemas/CaptureRequest"},examples:{layers:{summary:"Layers over a bounding box",value:{layers:["Layers.IMAGERY","Layers.OSM_BRIGHT"],bbox:[1.89,43.28,2.01,43.34],size:{width:1024,height:768}}},geojson:{summary:"GeoJSON features rendered as an overlay",value:{layers:["Layers.IMAGERY"],type:"FeatureCollection",features:[{type:"Feature",geometry:{type:"Point",coordinates:[3,42.5]},properties:{"fill-color":"#AAAAAA"}}]}},rawContent:{summary:"Raw file content imported in the application",value:{type:"kml",content:"<kml>...</kml>"}}}}}},responses:{200:{description:"The rendered snapshot",content:{"image/png":{schema:{type:"string",format:"binary"}}}},404:{description:"Invalid `layers` (not an array) or `size` (width or height outside 256–5000). The service answers `404` rather than `400` on these two validations.",content:{"application/json":{schema:{$ref:"#/components/schemas/Error"},example:{message:'Invalid "size" property'}}}},422:{description:"The body is a GeoJSON object but does not validate",content:{"application/json":{schema:{$ref:"#/components/schemas/ValidationError"}}}},500:{description:"The capture failed — most often the application could not be reached or rendered in time",content:{"application/json":{schema:{$ref:"#/components/schemas/Error"},example:{message:"Internal service error"}}}}}}}},h={securitySchemes:{bearerAuth:{type:"http",scheme:"bearer",bearerFormat:"JWT",description:"Paste a Kalisio JWT access token to authorize requests sent through the API gateway. The service itself does not check it: reached directly on its own port it answers without a token. Not to be confused with the `jwt` body property, which is the token kapture uses to log into the captured application."}},schemas:{CaptureRequest:{type:"object",description:"Every property is optional — an empty body captures the default view of the application configured through the environment variables.",properties:{layers:{type:"array",items:{type:"string"},description:"Layers to display, using the Kano formalism (`Layers.MY_LAYER`). For backward compatibility the kebab case form is also accepted, with or without the `layers-` prefix. Anything else than an array is rejected with a `404`.",example:["Layers.IMAGERY"]},bbox:{type:"array",items:{type:"number"},minItems:4,maxItems:4,description:"Bounding box of the zone to display as `[minLon, minLat, maxLon, maxLat]`. Ignored when `type` is set, as the view is then framed on the imported data.",example:[1.89,43.28,2.01,43.34]},time:{type:"string",format:"date-time",description:"Time to display, forwarded to the application as a query parameter.",example:"2026-08-14T09:00:00.000Z"},path:{type:"string",description:"Frontend URL path of the activity to capture. Defaults to `/#/home` followed by `activity`.",example:"/#/home/map"},activity:{type:"string",description:"Activity appended to the default path when `path` is not set.",default:"map",example:"map"},size:{type:"object",description:"Viewport size in pixels. Both dimensions must be between 256 and 5000, otherwise the request is rejected with a `404`.",properties:{width:{type:"integer",minimum:256,maximum:5e3,default:1024},height:{type:"integer",minimum:256,maximum:5e3,default:768}}},lang:{type:"string",description:"Language advertised to the page, which drives the application locale.",default:"en-US",example:"fr-FR"},type:{type:"string",description:"Either a GeoJSON type (`Feature`, `FeatureCollection`) when the body itself is the data, or the format of the raw `content` to import (`kml`, `geojson`, …).",example:"kml"},content:{type:"string",description:"Raw data to import in the application, rendered as an overlay. Requires `type`.",example:"<kml>...</kml>"},encoding:{type:"string",enum:["base64"],description:"Set it to `base64` when `content` is encoded, e.g. for binary formats."},features:{type:"array",items:{type:"object"},description:"GeoJSON features, when the body is a `FeatureCollection`."},geometry:{type:"object",description:"GeoJSON geometry, when the body is a single `Feature`."},properties:{type:"object",description:"GeoJSON properties, when the body is a single `Feature`. Styling properties such as `fill-color` are honoured by the application."},parameters:{type:"object",description:"Additional query parameters forwarded to the activity. Array values are repeated.",example:{sublegend:"weather"}},layout:{type:"object",description:"Overrides the application layout. Defaults to hiding every pane and the floating action button; an empty object leaves the layout untouched.",example:{panes:{left:{opener:!1,visible:!1},top:{opener:!1,visible:!1},right:{opener:!1,visible:!1},bottom:{opener:!1,visible:!1}},fab:{visible:!1}}},url:{type:"string",description:"URL of the application to capture. Defaults to the `APP_URL` environment variable.",example:"https://kano.dev.kalisio.xyz"},jwt:{type:"string",description:"Token written to the application local storage so the captured session is authenticated. Defaults to the `APP_JWT` environment variable."},appName:{type:"string",description:"Application name, used as the local storage key prefix. Defaults to the `APP_NAME` environment variable.",example:"kano"},delay:{type:"integer",description:"Delay in milliseconds between the end of the rendering and the screenshot. Defaults to the `DELAY` environment variable.",default:2e3},pageSetupDelay:{type:"integer",description:"Delay in milliseconds after navigation, letting the activity set itself up. Defaults to the `PAGE_SETUP_DELAY` environment variable.",default:2e3},uploadFileDelay:{type:"integer",description:"Delay in milliseconds after uploading the imported data. Defaults to the `UPLOAD_FILE_DELAY` environment variable.",default:2e3},networkdIdleTimeout:{type:"integer",description:"Maximum time in milliseconds to wait for the network to be idle. Defaults to the `NETWORK_IDLE_TIMEOUT` environment variable. Note the spelling, kept as-is in the implementation.",default:1e5}}},Error:{type:"object",properties:{message:{type:"string",example:"Internal service error"}}},ValidationError:{type:"object",properties:{message:{type:"string",example:'Invalid "GeoJSON"'},errors:{type:"array",items:{type:"string"},description:"The GeoJSON validation errors."}}}}},d={openapi:n,info:s,security:p,tags:c,paths:l,components:h},b=JSON.parse('{"title":"API","description":"service-kapture HTTP API reference","frontmatter":{"title":"API","description":"service-kapture HTTP API reference"},"headers":[],"relativePath":"packages/service-kapture/service-kapture-openapi.md","filePath":"packages/service-kapture/service-kapture-openapi.md"}'),m={name:"packages/service-kapture/service-kapture-openapi.md"},v=Object.assign(m,{setup(u){return(y,f)=>{const e=t("OASpec");return a(),i("div",null,[r(e,{spec:o(d),hideBranding:!0},null,8,["spec"])])}}});export{b as __pageData,v as default};
